:root { font-family: system-ui, sans-serif; color: #172c3c; background: #f4f7f9; }
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 800px; margin: 64px auto; padding: 0 24px; }
.brand { color: #476c80; font-size: 12px; font-weight: 700; letter-spacing: .16em; }
h1 { font-size: 36px; margin: 12px 0 32px; overflow-wrap: anywhere; }
h2 { font-size: 20px; margin-top: 36px; }
form { padding: 24px; background: white; border: 1px solid #dce4e9; border-radius: 10px; }
label { display: block; font-weight: 600; margin-bottom: 10px; }
.form-controls { display: flex; gap: 12px; }
input { min-width: 0; flex: 1; border: 1px solid #92a7b4; border-radius: 6px; padding: 11px; font: inherit; }
button { border: 1px solid #245872; border-radius: 6px; background: #245872; color: white; padding: 11px 16px; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #173f55; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #ce8b22; outline-offset: 3px; }
.project-row { display: flex; justify-content: space-between; align-items: center; gap: 20px; background: white; border: 1px solid #dce4e9; border-radius: 8px; padding: 18px; margin: 12px 0; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row button { flex-shrink: 0; background: white; color: #245872; }
.project-row button:hover { background: #eef4f7; }
#alert { color: #8c2020; background: #fff0ee; border: 1px solid #e2aca6; padding: 14px; border-radius: 6px; }
#empty { color: #536875; }
#create-task { margin-top: 24px; }
select { border: 1px solid #92a7b4; border-radius: 6px; padding: 10px; font: inherit; background: white; color: inherit; }
.task-row { display: flex; align-items: center; gap: 14px; background: white; border: 1px solid #dce4e9; border-radius: 8px; padding: 18px; margin: 12px 0; }
.task-row input { flex: none; width: 20px; height: 20px; margin: 0; }
.task-row span { min-width: 0; overflow-wrap: anywhere; }
@media (max-width: 520px) { main { margin-top: 32px; } .form-controls { flex-direction: column; } .project-row { align-items: flex-start; flex-direction: column; } }

